{
	private NonNullList<ItemStack> inventory = NonNullList.withSize(1, ItemStack.EMPTY);

	private int sharpness;

	private int fire;

	private int blast;

	private int smite;

	private int bane;

	private int damageCooldown;

	private int damage;

	public int getBlastResistance()
	{
		return blast;
	}

	@Override
