			NBTTagCompound ench = (NBTTagCompound) list.get(i);

			int id = ench.getShort("id");
			int lvl = ench.getShort("lvl");

			if (Enchantment.REGISTRY.getIDForObject(Enchantments.SHARPNESS) == id)
